begin;
create or replace function public.publish_game_story_to_news()
returns trigger language plpgsql security definer set search_path=public as $$
declare story_slug text; winner_team uuid; begin if new.status<>'published' or (tg_op='UPDATE' and old.status='published') then return new; end if; story_slug:='game-'||replace(new.game_id::text,'-',''); select case when g.home_score>=g.away_score then g.home_team_id else g.away_team_id end into winner_team from public.games g where g.id=new.game_id; insert into public.news(author_id,title,slug,excerpt,body,status,published_at,updated_at,team_id) values(new.approved_by,new.headline,story_slug,new.summary,coalesce(new.story_body,new.summary),'published',coalesce(new.published_at,now()),now(),winner_team) on conflict(slug) do update set author_id=excluded.author_id,title=excluded.title,excerpt=excluded.excerpt,body=excluded.body,status='published',published_at=excluded.published_at,updated_at=now(),team_id=excluded.team_id; return new; end $$;
drop trigger if exists publish_game_story_to_news_after_write on public.game_story_drafts; create trigger publish_game_story_to_news_after_write after insert or update of status on public.game_story_drafts for each row execute function public.publish_game_story_to_news(); revoke execute on function public.publish_game_story_to_news() from public,anon,authenticated;
commit;
